"""Provide current-task page methodology without changing native permissions."""

from collections import Counter

from pydantic import JsonValue

from experimental.curator.harness.preparation import PreparationRequest
from experimental.curator.harness.resources import (
    CapabilityContribution,
    CapabilityRegistrar,
    CapabilitySelection,
    RegistrationReceipt,
    SelectionRequest,
    SkillContribution,
    SkillSelection,
)
from experimental.curator.harness.state import Task
from experimental.curator.harness.strategies import CapabilityStrategy


SKILL_NAME = "brand-booking-page"
SKILL_SOURCE = "curator-capability"
SKILL_ASSET = "skills/brand-booking-page/SKILL.md"
GUIDANCE = """制作或修改品牌预订页时，正文可用则先对照随附 brand-booking-page 方法与成对案例：
以本次完整品牌规则和内容数据为依据；旧稿只是修改对象，上一家门店的规则不沿用。
已在当前上下文完整读到且未变的材料不要重复读取；缺段、变更或需定位依据时再补读。
当次规则按 h1—h6 与其他文字规定字体首项时，写样式前按实际元素落实两类字体；店名、产品名不因醒目例外。把有效 font-family 首项核对并入已有双端检查，不靠外观或本机回退判定，也不下载字体或强改标签避错。
先完成自包含、可离线显示的单文件 HTML，按本次要求安排首屏，再用实际可用浏览器检查手机和桌面并查看截图；修正后复看受影响部分。
不要把媒体查询、源码检查或截图路径当作视觉检查通过。检查失败仍交付有依据的可用页面，不用计划或说明代替页面、不虚报通过；未验证项内部留存，仅当本次交付格式允许时准确说明，不额外附报告或塞入顾客页面。
使用 deliver_files 交付磁盘上的最终文件，成功回执才证明已交付，回复遵守当次极简格式。保留正常预订链接；离线显示不等于外部预订服务离线可用。遵守工具权限，不以其他渠道绕过拒绝。"""


class BrandPageCapability(CapabilityStrategy):
    def __init__(self, registrar: CapabilityRegistrar) -> None:
        self._registrar = registrar

    def _prepare_skills(self, request: PreparationRequest) -> tuple[SkillContribution, ...]:
        body = request.assets[SKILL_ASSET]
        if not body.strip():
            raise ValueError(f"Required skill asset is empty: {SKILL_ASSET}")
        return (
            SkillContribution(
                name=SKILL_NAME,
                owner="capability",
                package=None,
                files={"SKILL.md": body},
                source="Task and owner requirements: current-brand offline booking pages",
            ),
        )

    def register(self, contribution: CapabilityContribution) -> RegistrationReceipt:
        return self._registrar.register(contribution)

    async def select(self, request: SelectionRequest) -> CapabilitySelection:
        # Selection must remain unambiguous under the host's exact-identity lookup.
        counts = Counter((skill.source, skill.name) for skill in request.skills)
        available = tuple(
            skill for skill in request.skills
            if skill.available and counts[(skill.source, skill.name)] == 1
        )
        owned = (SKILL_SOURCE, SKILL_NAME)
        if not any((skill.source, skill.name) == owned for skill in available):
            return CapabilitySelection(
                tools=None,
                skills=None,
                guidance="brand-booking-page 方法正文当前缺失、不可用或身份不唯一；本次未选择其正文，不能声称已送达。按以下核心方法继续：\n" + GUIDANCE,
            )
        selections = tuple(
            SkillSelection(
                name=skill.name,
                source=skill.source,
                delivery="body" if (skill.source, skill.name) == owned else "catalog",
            )
            for skill in available
        )
        guidance = GUIDANCE
        if any(count > 1 for count in counts.values()):
            guidance += "\n能力目录中有重复身份的 Skill，未显式选择这些歧义项；不要声称它们已送达。"
        return CapabilitySelection(tools=None, skills=selections, guidance=guidance)


def create(
    state: dict[str, JsonValue], task: Task, *, registrar: CapabilityRegistrar
) -> BrandPageCapability:
    # Task identity and the session checkpoint remain entirely host-owned.
    return BrandPageCapability(registrar)
